[CmdletBinding(SupportsShouldProcess)]
param([Parameter(Mandatory)][ValidateSet('copilot','claude')][string]$Provider,[switch]$DeviceCode,[string]$ConfigPath=(Join-Path (Split-Path -Parent $PSScriptRoot) 'config\agents.json'),[string]$CodexHome)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'AgentEcosystem.psm1') -Force;$config=Get-EcosystemConfig -ConfigPath $ConfigPath -CodexHome $CodexHome;$command=[string]$config.providerRouting.providers.PSObject.Properties[$Provider].Value.command;if(-not ((Get-Command $command -ErrorAction SilentlyContinue) -or(Test-Path -LiteralPath $command -PathType Leaf))){throw "Provider '$Provider' is not installed."};$arguments=@('login');if($Provider -eq 'copilot' -and $DeviceCode){$arguments+='--device-code'};if($PSCmdlet.ShouldProcess($Provider,'Start provider-owned interactive login')){& $command @arguments;if($LASTEXITCODE -ne 0){throw "Provider '$Provider' login failed with exit code $LASTEXITCODE."}};[pscustomobject]@{provider=$Provider;started=$true;secretsStoredByEcosystem=$false}
